package com.jarvis.ai;

import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.os.*;import android.speech.*;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import androidx.core.app.ActivityCompat;import androidx.core.content.ContextCompat;import java.util.*;

public class MainActivity extends AppCompatActivity {
    private static final int MIC=50,SPEECH=60; private TextView status,transcript; private JarvisEngine engine;private JarvisTts tts;private JarvisActionExecutor executor;private final JarvisCommandRouter router=new JarvisCommandRouter();
    @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);status=findViewById(R.id.status);transcript=findViewById(R.id.transcript);engine=new JarvisEngine(this);tts=new JarvisTts(this);executor=new JarvisActionExecutor(this);
        findViewById(R.id.startWake).setOnClickListener(v->startWake());findViewById(R.id.stopWake).setOnClickListener(v->stopWake());findViewById(R.id.speak).setOnClickListener(v->listen());findViewById(R.id.clearMemory).setOnClickListener(v->{engine.memory().clear();status.setText("Local memory cleared.");});findViewById(R.id.settings).setOnClickListener(v->settings());findViewById(R.id.accessibility).setOnClickListener(v->startActivity(new Intent(android.provider.Settings.ACTION_ACCESSIBILITY_SETTINGS)));if(getIntent().getBooleanExtra("wake",false))new Handler().postDelayed(this::listen,350);}
    private boolean mic(){return ContextCompat.checkSelfPermission(this,Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED;}
    private void startWake(){if(!mic()){ActivityCompat.requestPermissions(this,new String[]{Manifest.permission.RECORD_AUDIO},MIC);return;}ContextCompat.startForegroundService(this,new Intent(this,JarvisWakeService.class));status.setText("Wake listener active.");}
    private void stopWake(){stopService(new Intent(this,JarvisWakeService.class));status.setText("Wake listener stopped.");}
    private void listen(){if(!mic()){ActivityCompat.requestPermissions(this,new String[]{Manifest.permission.RECORD_AUDIO},MIC);return;}Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);i.putExtra(RecognizerIntent.EXTRA_PARTIAL_RESULTS,false);startActivityForResult(i,SPEECH);status.setText("Listening…");}
    @Override protected void onActivityResult(int r,int code,Intent data){super.onActivityResult(r,code,data);if(r!=SPEECH||data==null)return;ArrayList<String>a=data.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS);if(a==null||a.isEmpty())return;String cmd=a.get(0);transcript.setText(cmd);execute(cmd);}
    private void execute(String cmd){JarvisAction a=router.route(cmd);if(a.confirmation)new AlertDialog.Builder(this).setTitle("JARVIS Confirmation").setMessage("এই কাজটি করতে অনুমতি দেবেন?\n"+cmd).setNegativeButton("Cancel",null).setPositiveButton("Confirm",(d,w)->run(a)).show();else run(a);}
    private void run(JarvisAction a){if(a.type==JarvisAction.Type.ASK_AI){status.setText("Thinking…");new Thread(()->{String answer=engine.ask(a.value);runOnUiThread(()->{status.setText(answer);tts.speak(answer);});}).start();return;}String result;if(a.type==JarvisAction.Type.HOME||a.type==JarvisAction.Type.BACK||a.type==JarvisAction.Type.RECENTS||a.type==JarvisAction.Type.NOTIFICATIONS||a.type==JarvisAction.Type.QUICK_SETTINGS||a.type==JarvisAction.Type.SCROLL_UP||a.type==JarvisAction.Type.SCROLL_DOWN||a.type==JarvisAction.Type.OPEN_APP)result=executor.execute(a);else if(a.type==JarvisAction.Type.CALL)result="Call confirmation accepted. Phone-number/contact resolution can be added next.";else if(a.type==JarvisAction.Type.SMS)result="SMS confirmation accepted. Message/contact composition can be added next.";else result="Done.";status.setText(result);tts.speak(result);}
    private void settings(){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(30,10,30,10);EditText gem=new EditText(this);gem.setHint("Gemini API key");gem.setInputType(129);EditText open=new EditText(this);open.setHint("OpenAI API key");open.setInputType(129);EditText groq=new EditText(this);groq.setHint("Groq API key");groq.setInputType(129);EditText custom=new EditText(this);custom.setHint("Custom API key");custom.setInputType(129);EditText endpoint=new EditText(this);endpoint.setHint("Custom OpenAI-compatible endpoint");Spinner primary=new Spinner(this);String[]ps={"Gemini","OpenAI-compatible","Groq","Custom"};primary.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,ps));box.addView(primary);box.addView(gem);box.addView(open);box.addView(groq);box.addView(custom);box.addView(endpoint);new AlertDialog.Builder(this).setTitle("JARVIS AI Settings").setView(box).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->{if(gem.getText().length()>0)SecureStore.put(this,"gemini",gem.getText().toString());if(open.getText().length()>0)SecureStore.put(this,"openai",open.getText().toString());if(groq.getText().length()>0)SecureStore.put(this,"groq",groq.getText().toString());if(custom.getText().length()>0)SecureStore.put(this,"custom",custom.getText().toString());if(endpoint.getText().length()>0)SecureStore.put(this,"custom_endpoint",endpoint.getText().toString());SecureStore.put(this,"primary",primary.getSelectedItem().toString());status.setText("AI settings saved securely.");}).show();}
    @Override protected void onDestroy(){if(tts!=null)tts.shutdown();super.onDestroy();}
}
